package estate.svc;

import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

class MainTest {
    private Main start(FakeContext c) throws Exception {
        Main m = new Main();
        m.start(c);
        return m;
    }

    @Test
    void statementFollowsPaymentEvents() throws Exception {
        FakeContext c = new FakeContext();
        Main m = start(c);
        m.onEvent("payment.posted", Map.of("account", "a1", "amount", "12.50", "requestId", "r1"));
        m.onEvent("payment.posted", Map.of("account", "a1", "amount", "7.25", "requestId", "r2"));
        Map<String, String> s = m.handle("statement", Map.of("account", "a1"));
        assertEquals("19.75", s.get("balance"));
        assertEquals("2", s.get("lines"));
    }

    @Test
    void payRetriesTimeoutsWithIdempotencyAndAttemptRequestIds() throws Exception {
        FakeContext c = new FakeContext();
        Main m = start(c);
        List<Map<String, String>> attempts = new ArrayList<>();
        c.stubs.put("ledger.post", r -> {
            attempts.add(new HashMap<>(r));
            if (attempts.size() < 3) throw new estate.api.ServiceException("timeout", "lost");
            return Map.of("id", "1", "dup", "false");
        });

        assertEquals("OK", m.handle("pay", Map.of("customerId", "c1", "account", "a1", "amount", "5.00", "ref", "r1")).get("status"));
        assertEquals(3, attempts.size());
        for (Map<String, String> attempt : attempts) assertEquals("r1", attempt.get("idempotencyKey"));
        assertEquals("r1-1", attempts.get(0).get("requestId"));
        assertEquals("r1-2", attempts.get(1).get("requestId"));
        assertEquals("r1-3", attempts.get(2).get("requestId"));

        attempts.clear();
        c.stubs.put("ledger.post", r -> {
            attempts.add(new HashMap<>(r));
            throw new estate.api.ServiceException("timeout", "lost");
        });
        Map<String, String> failed = m.handle("pay", Map.of("customerId", "c1", "account", "a1", "amount", "5.00", "ref", "r2"));
        assertEquals("FAILED", failed.get("status"));
        assertEquals("timeout", failed.get("reason"));
        assertEquals(3, attempts.size());
        assertEquals(List.of("r2-1", "r2-2", "r2-3"), attempts.stream().map(r -> r.get("requestId")).toList());
    }

    @Test
    void applyUsesScoreThresholds() throws Exception {
        FakeContext c = new FakeContext();
        Main m = start(c);
        c.stubs.put("decision.score", r -> Map.of("score", "65"));
        assertEquals("APPROVE", m.handle("apply", Map.of("customerId", "c1", "income", "1000", "amount", "100")).get("decision"));
        c.stubs.put("decision.score", r -> Map.of("score", "45"));
        assertEquals("REFER", m.handle("apply", Map.of("customerId", "c1", "income", "1000", "amount", "100")).get("decision"));
        c.stubs.put("decision.score", r -> Map.of("score", "10"));
        assertEquals("DECLINE", m.handle("apply", Map.of("customerId", "c1", "income", "1000", "amount", "100")).get("decision"));
    }

    @Test
    void offersNeedConsent() throws Exception {
        FakeContext c = new FakeContext();
        Main m = start(c);
        m.handle("create", Map.of("customerId", "c1", "consent", "explicit"));
        m.handle("create", Map.of("customerId", "c2", "consent", "none"));
        assertEquals("true", m.handle("offer", Map.of("customerId", "c1", "offerId", "o1")).get("queued"));
        assertEquals("false", m.handle("offer", Map.of("customerId", "c2", "offerId", "o1")).get("queued"));
        assertEquals(1, c.events.size());
    }
}
package estate.svc;

import estate.api.Context;
import estate.api.ServiceException;

import java.sql.Connection;
import java.sql.DriverManager;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;

/** Test double for the platform: in-memory H2, stubbed calls, recorded events. */
public class FakeContext implements Context {
    private static final AtomicInteger N = new AtomicInteger();

    public interface Stub { Map<String, String> apply(Map<String, String> req) throws ServiceException; }

    public final Map<String, Stub> stubs = new HashMap<>();
    public final List<String> published = new ArrayList<>();
    public final List<Map<String, String>> events = new ArrayList<>();
    public long tick = 0;
    private final Connection db;

    public FakeContext() {
        try {
            db = DriverManager.getConnection("jdbc:h2:mem:test" + N.incrementAndGet() + ";DB_CLOSE_DELAY=-1");
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    public Connection db() { return db; }

    public Map<String, String> call(String service, String op, Map<String, String> request) throws ServiceException {
        Stub s = stubs.get(service + "." + op);
        if (s == null) throw new ServiceException("unavailable", "no stub for " + service + "." + op);
        return s.apply(request);
    }

    public void publish(String topic, Map<String, String> event) { published.add(topic); events.add(event); }

    public long now() { return tick; }
}

package estate.svc;

import estate.api.Context;
import estate.api.Service;
import estate.api.ServiceException;

import java.math.BigDecimal;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.HashMap;
import java.util.Map;

/**
 * Customer: profiles and consent, payments (through the ledger), a statement read model built from ledger events,
 * credit applications (through the decision service) and marketing offers.
 */
public class Main implements Service {
    private Context ctx;
    private Connection db;

    @Override
    public void start(Context c) throws Exception {
        this.ctx = c;
        this.db = c.db();
        try (Statement s = db.createStatement()) {
            s.execute("CREATE TABLE IF NOT EXISTS customers(id VARCHAR(40) PRIMARY KEY, consent VARCHAR(20) NOT NULL)");
            s.execute("CREATE TABLE IF NOT EXISTS statement(account VARCHAR(40) PRIMARY KEY, balance_cents BIGINT NOT NULL, lines INT NOT NULL)");
        }
    }

    @Override
    public Map<String, String> handle(String op, Map<String, String> req) throws ServiceException {
        try {
            switch (op) {
                case "health": {
                    try (Statement s = db.createStatement(); ResultSet rs = s.executeQuery("SELECT COUNT(*) FROM customers")) { rs.next(); }
                    return Map.of("status", "UP");
                }
                case "create": return create(req);
                case "pay": return pay(req);
                case "statement": return statement(req);
                case "apply": return apply(req);
                case "offer": return offer(req);
                case "consent.check": return consentCheck(req);
                default: throw new ServiceException("error", "unknown op " + op);
            }
        } catch (ServiceException e) {
            throw e;
        } catch (Exception e) {
            throw new ServiceException("error", String.valueOf(e.getMessage()));
        }
    }

    /** consent is one of: none, implied (legacy customers), explicit. */
    private Map<String, String> create(Map<String, String> req) throws Exception {
        try (PreparedStatement ins = db.prepareStatement("INSERT INTO customers(id, consent) VALUES (?,?)")) {
            ins.setString(1, req.get("customerId"));
            ins.setString(2, req.get("consent"));
            ins.executeUpdate();
        }
        return Map.of("status", "OK");
    }

    private Map<String, String> pay(Map<String, String> req) throws Exception {
        for (int attempt = 1; attempt <= 3; attempt++) {
            Map<String, String> post = new HashMap<>();
            post.put("account", req.get("account"));
            post.put("amount", req.get("amount"));
            post.put("idempotencyKey", req.get("ref"));
            post.put("requestId", req.get("ref") + "-" + attempt);
            try {
                ctx.call("ledger", "post", post);
                return Map.of("status", "OK");
            } catch (ServiceException e) {
                if (!"timeout".equals(e.code)) throw e;
                if (attempt == 3) return Map.of("status", "FAILED", "reason", "timeout");
            }
        }
        throw new AssertionError("unreachable");
    }

    @Override
    public void onEvent(String topic, Map<String, String> ev) throws Exception {
        if (!"payment.posted".equals(topic)) return;
        long cents = new BigDecimal(ev.get("amount")).movePointRight(2).longValueExact();
        try (PreparedStatement up = db.prepareStatement("UPDATE statement SET balance_cents = balance_cents + ?, lines = lines + 1 WHERE account = ?")) {
            up.setLong(1, cents);
            up.setString(2, ev.get("account"));
            if (up.executeUpdate() == 0) {
                try (PreparedStatement ins = db.prepareStatement("INSERT INTO statement(account, balance_cents, lines) VALUES (?,?,1)")) {
                    ins.setString(1, ev.get("account"));
                    ins.setLong(2, cents);
                    ins.executeUpdate();
                }
            }
        }
    }

    private Map<String, String> statement(Map<String, String> req) throws Exception {
        try (PreparedStatement q = db.prepareStatement("SELECT balance_cents, lines FROM statement WHERE account = ?")) {
            q.setString(1, req.get("account"));
            try (ResultSet rs = q.executeQuery()) {
                if (!rs.next()) return Map.of("balance", "0.00", "lines", "0");
                return Map.of("balance", BigDecimal.valueOf(rs.getLong(1), 2).toPlainString(), "lines", String.valueOf(rs.getInt(2)));
            }
        }
    }

    /** Approve at a score of 60 or more, refer at 40 or more, otherwise decline. */
    private Map<String, String> apply(Map<String, String> req) throws Exception {
        Map<String, String> r = ctx.call("decision", "score", Map.of("income", req.get("income"), "amount", req.get("amount")));
        int score = Integer.parseInt(r.get("score"));
        String decision = score >= 60 ? "APPROVE" : score >= 40 ? "REFER" : "DECLINE";
        return Map.of("decision", decision, "score", String.valueOf(score));
    }

    private String consentOf(String customerId) throws Exception {
        try (PreparedStatement q = db.prepareStatement("SELECT consent FROM customers WHERE id = ?")) {
            q.setString(1, customerId);
            try (ResultSet rs = q.executeQuery()) { return rs.next() ? rs.getString(1) : "none"; }
        }
    }

    private Map<String, String> consentCheck(Map<String, String> req) throws Exception {
        String c = consentOf(req.get("customerId"));
        boolean allowed = c.equals("implied") || c.equals("explicit");
        return Map.of("allowed", String.valueOf(allowed), "basis", c);
    }

    private Map<String, String> offer(Map<String, String> req) throws Exception {
        String c = consentOf(req.get("customerId"));
        if (!(c.equals("implied") || c.equals("explicit"))) return Map.of("queued", "false");
        ctx.publish("offer.queued", Map.of("customerId", req.get("customerId"), "offerId", req.get("offerId")));
        return Map.of("queued", "true");
    }
}
package estate.api;

import java.sql.Connection;
import java.util.Map;

/** What the platform gives an instance. The database is shared by every instance and every version of the service. */
public interface Context {
    Connection db();

    /** Synchronous call to another service. Throws ServiceException with code "timeout", "unavailable" or "error". */
    Map<String, String> call(String service, String op, Map<String, String> request) throws ServiceException;

    /** Publish an event; consumers receive it a few ticks later. */
    void publish(String topic, Map<String, String> event);

    /** Platform clock (ticks). */
    long now();
}
package estate.api;

import java.util.Map;

/** A deployable service. One instance of the implementing class runs per deployed instance of the service. */
public interface Service {
    /** Called once when an instance starts. Run your schema migrations here. */
    void start(Context ctx) throws Exception;

    /** Handle a synchronous request. `op` and the maps are the service's published contract. */
    Map<String, String> handle(String op, Map<String, String> req) throws ServiceException;

    /** Handle an asynchronous event from a topic this service subscribes to. */
    default void onEvent(String topic, Map<String, String> event) throws Exception {}
}
package estate.api;

public class ServiceException extends Exception {
    public final String code;

    public ServiceException(String code, String message) {
        super(message);
        this.code = code;
    }
}

